    def parse_ref_link(self, m: Match[str], state: BlockState) -> Optional[int]:
        """Parse link references and save the link information into ``state.env``.

        Here is an example of a link reference:

        .. code-block:: markdown

            a [link][example]

            [example]: https://example.com "Optional title"

        This method will save the link reference into ``state.env`` as::

            state.env['ref_links']['example'] = {
                'url': 'https://example.com',
                'title': "Optional title",
            }
        """
        end_pos = state.append_paragraph()
        if end_pos:
            return end_pos

        label = m.group("reflink_1")
        key = self._normalize_ref_key(label)
        if not key:
            return None

        href, href_pos = parse_link_href(
            state.src, m.end(), block=True, max_nested_level=self.max_nested_level
        )
        if href is None:
            return None

        assert href_pos is not None

        max_pos = self._find_max_pos_for_ref(state, href_pos)
        title, title_pos = parse_link_title(state.src, href_pos, max_pos)
        title_pos = self._adjust_title_pos(state, title_pos)
        href_pos = self._adjust_href_pos(state, href_pos, title_pos)

        end_pos = title_pos or href_pos
        if not end_pos:
            return None

        self._store_ref_link(state, key, label, href)
        return end_pos

    @staticmethod
    def _normalize_ref_key(label: str) -> str:
        """Normalize a reference label to its canonical key form."""
        return ' '.join(label.split()).strip().lower().upper()

    def _find_max_pos_for_ref(self, state: BlockState, href_pos: int) -> int:
        """Find the maximum position for parsing the title of a reference link."""
        blank_pos = _find_next_blank_line(state, href_pos, self.BLANK_LINE)
        if blank_pos is None:
            return state.cursor_max
        return blank_pos

    @staticmethod
    def _adjust_title_pos(state: BlockState, title_pos: Optional[int]) -> Optional[int]:
        """Adjust the title position to include trailing whitespace/newline."""
        if title_pos:
            m = _BLANK_TO_LINE.match(state.src, title_pos)
            if m:
                return m.end()
            return None
        return None

    @staticmethod
    def _adjust_href_pos(
        state: BlockState, href_pos: int, title_pos: Optional[int]
    ) -> Optional[int]:
        """Adjust the href position if there is no title."""
        if title_pos is None:
            m = _BLANK_TO_LINE.match(state.src, href_pos)
            if m:
                return m.end()
            return None
        return href_pos

    @staticmethod
    def _store_ref_link(
        state: BlockState, key: str, label: str, href: str
    ) -> None:
        """Store the reference link in state.env if not already present."""
        if key not in state.env["ref_links"]:
            href = unescape_char(href)
            data = {"url": escape_url(href), "label": label}
            state.env["ref_links"][key] = data
