    def finalize_tokens(self, tokens: List[Dict[str, Any]], depth: int) -> List[Dict[str, Any]]:
        remaining = self.max_nested_level - depth
        tokens2 = tokens
        enabled = 'emphasis' in self.rules and remaining > 0
        if len(tokens2) > 1:
            tokens2 = _coalesce_emphasis_text(tokens2)
        if not enabled or not _contains_emphasis_marker(tokens2):
            return [_clean_emphasis_token(token) for token in tokens2]
        parts: List[Dict[str, Any]] = []
        delimiters: List[_Delimiter] = []
        source = _emphasis_source_text(tokens2)
        source_pos = 0
        for token in tokens2:
            if token['type'] == 'text' and token.get('_emphasis', True):
                _split_text_token(token, source, source_pos, parts, delimiters)
            else:
                parts.append(_clean_emphasis_token(token))
            source_pos += _emphasis_source_length(token)
        if _process_dense_emphasis(parts, delimiters):
            return _merge_text_tokens(parts)
        _process_emphasis_delimiters(parts, delimiters, remaining)
        return _merge_text_tokens(parts)
