    def finalize_tokens(self, tokens: List[Dict[str, Any]], depth: int) -> List[Dict[str, Any]]:
        remaining = self.max_nested_level - depth
        tokens = _coalesce_emphasis_text(tokens) if len(tokens) > 1 else tokens
        if not self._emphasis_enabled(remaining) or not _contains_emphasis_marker(tokens):
            return [_clean_emphasis_token(token) for token in tokens]
        return self._process_emphasis_tokens(tokens, remaining)

    def _emphasis_enabled(self, remaining: int) -> bool:
        return "emphasis" in self.rules and remaining > 0

    def _process_emphasis_tokens(self, tokens: List[Dict[str, Any]], remaining: int) -> List[Dict[str, Any]]:
        parts: List[Dict[str, Any]] = []
        delimiters: List[_Delimiter] = []
        source = _emphasis_source_text(tokens)
