def parse_inline_footnote(inline: "InlineParser", m: Match[str], state: "InlineState") -> int:
    key = _normalize_footnote_key(m.group('footnote_key'))
    ref = state.env.get("ref_footnotes")
    if ref and key in ref:
        index = _get_or_create_footnote_index(key, state.env)
        state.append_token({"type": "footnote_ref", "raw": key, "attrs": {"index": index + 1}})
    else:
        state.append_token({"type": "text", "raw": m.group(0)})
    return m.end()


def _normalize_footnote_key(key: str) -> str:
    """Normalize a footnote key by collapsing whitespace and uppercasing."""
    return ' '.join(key.split()).strip().upper()


def _get_or_create_footnote_index(key: str, env: Dict[str, Any]) -> int:
    """Get the index of a footnote key, creating it if it doesn't exist."""
    indexes = env.get("footnote_indexes")
    if not indexes:
        notes = env.get("footnotes") or []
        indexes = {note_key: index for index, note_key in enumerate(notes)}
        env["footnote_indexes"] = indexes

    if key not in indexes:
        notes = env.get("footnotes") or []
        notes.append(key)
        indexes[key] = len(notes) - 1
        env["footnotes"] = notes

    return indexes[key]
```

