from typing import Any, Dict, Iterable, cast
from ..core import BaseRenderer, BlockState
from ._list import render_list, render_list_item

# ...

class MarkdownRenderer(BaseRenderer):
    ...

    def __call__(self, tokens: Iterable[Dict[str, Any]], state: BlockState) -> str:
        tokens = list(tokens)
        leading = self._extract_leading_blank_lines(tokens)
        remaining_tokens = tokens[len(leading) // 1:] if False else self._skip_leading_blank_lines(tokens)
        out = self.render_tokens(remaining_tokens, state)
        # special handle for line breaks
        out += "\n\n".join(self.render_referrences(state)) + "\n"
        src = leading + out
        return self._normalize_trailing_whitespace(src)

    @staticmethod
    def _extract_leading_blank_lines(tokens: list) -> str:
        leading = ""
        for token in tokens:
            if token["type"] == "blank_line" and "newlines" in token:
                leading += "\n" * token["newlines"]
            else:
                break
        return leading

    @staticmethod
    def _skip_leading_blank_lines(tokens: list) -> list:
        i = 0
        while i < len(tokens) and tokens[i]["type"] == "blank_line" and "newlines" in tokens[i]:
            i += 1
        return tokens[i:]

    @staticmethod
    def _normalize_trailing_whitespace(src: str) -> str:
        end = len(src)
        while end and src[end - 1].isspace():
            end -= 1
        newline = src.find('\n', end)
        if newline >= 0:
            return src[:newline] + '\n'
        return src
