    def __call__(self, tokens: Iterable[Dict[str, Any]], state: BlockState) -> str:
        tokens = list(tokens)
        leading = self._collect_leading_blank_lines(tokens)
        body = self.render_tokens(tokens[self._leading_blank_line_count(tokens):], state)
        references = "\n\n".join(self.render_referrences(state))
        src = leading + body + references + "\n"
        return self._normalize_trailing_whitespace(src)

    @staticmethod
    def _leading_blank_line_count(tokens: list) -> int:
        count = 0
        for token in tokens:
            if token["type"] == "blank_line" and "newlines" in token:
                count += 1
            else:
                break
        return count

    @classmethod
    def _collect_leading_blank_lines(cls, tokens: list) -> str:
        count = cls._leading_blank_line_count(tokens)
        total_newlines = sum(
            tokens[i]["newlines"] for i in range(count)
        )
        return "\n" * total_newlines

    @staticmethod
    def _normalize_trailing_whitespace(src: str) -> str:
        end = len(src)
        while end and src[end - 1].isspace():
            end -= 1
        newline = src.find('\n', end)
        if newline >= 0:
            return src[:newline] + '\n'
        return src
