def _ends_with_newline(leaf, suffix=''):
    """
    Check if the given leaf (or the nearest non-DEDENT error leaf before it)
    ends with a newline, or if the suffix ends with a newline.
    """
    # Walk backwards past DEDENT error leaves to find the relevant leaf
    while leaf is not None and leaf.type == 'error_leaf' and leaf.token_type == 'DEDENT':
        leaf = leaf.get_previous_leaf()

    # Determine the effective type of the leaf
    if leaf.type == 'error_leaf':
        effective_type = leaf.token_type.lower()
    else:
        effective_type = leaf.type

    return effective_type == 'newline' or suffix.endswith('\n') or suffix.endswith('\r')
```

