    self, spec: "_DeclSpec", decl: c_ast.Node | None, spec_coord: Coord | None
) -> c_ast.Node:
    """Build a parameter declaration from the given specifiers and declarator.

    If the last type in the spec is a typedef name in scope, the parameter
    is treated as a regular declaration. Otherwise, it is built as an
    abstract type (Typename).
    """
    if self._is_typedef_name_in_spec(spec):
        return self._build_declarations(spec=spec, decls=[{"decl": decl}])[0]

    typename = c_ast.Typename(
        name=None,
        quals=spec["qual"][:],
        align=None,
        type=decl or c_ast.TypeDecl(None, None, None, None),
        coord=spec_coord,
    )
    return cast(
        c_ast.Typename,
        self._attach_type_attributes(
            self._fix_decl_name_type(typename, spec["type"]), spec
        ),
    )

def _is_typedef_name_in_spec(self, spec: "_DeclSpec") -> bool:
    """Check if the last type in the spec is a typedef name in scope."""
    return (
        len(spec["type"]) > 1
        and isinstance(spec["type"][-1], c_ast.IdentifierType)
        and len(spec["type"][-1].names) == 1
        and self._is_type_in_scope(spec["type"][-1].names[0])
