    def _parse_attribute_specifier(self) -> c_ast.AttributeSpecifier:
        tok = self._tokens.next()
        if tok is None:
            self._parse_error('At end of input', self.clex.filename)
        if tok is not self._typedef_checked_token:
            self._classify_identifier(tok)
        opening = tok
        if self._dialect != "c23":
            self._parse_error("Attributes require C23", self._tok_coord(opening))
        attributes = self._parse_attribute_list()
        self._expect("ATTRIBUTE_END")
        return c_ast.AttributeSpecifier(attributes, self._tok_coord(opening))

    def _parse_attribute_list(self) -> list[c_ast.Attribute]:
        attributes = []
        while self._peek_type() != "ATTRIBUTE_END":
            if self._accept("COMMA"):
                continue
            attributes.append(self._parse_attribute())
            if not self._accept("COMMA"):
                break
        return attributes

    def _parse_attribute(self) -> c_ast.Attribute:
        name = self._parse_identifier_or_typeid()
        namespace = None
        if self._accept("COLONCOLON"):
            namespace = name.name
            name = self._parse_identifier_or_typeid()
        arguments = self._accept("ATTRIBUTE_ARGUMENTS")
        return c_ast.Attribute(
            name.name,
            namespace,
            arguments.value if arguments is not None else None,
            name.coord,
        )
