    def _parse_statement(self) -> c_ast.Node:
        if self._peek_type() == "ATTRIBUTE_BEGIN":
            return self._parse_attributed_statement()
        tok_type = self._peek_type()
        match tok_type:
            case "CASE" | "DEFAULT":
                return self._parse_labeled_statement()
            case "ID" if self._peek_type(2) == "COLON":
                return self._parse_labeled_statement()
            case "LBRACE":
                return self._parse_compound_statement()
            case "IF" | "SWITCH":
                return self._parse_selection_statement()
            case "WHILE" | "DO" | "FOR":
                return self._parse_iteration_statement()
            case "GOTO" | "BREAK" | "CONTINUE" | "RETURN":
                return self._parse_jump_statement()
            case "PPPRAGMA" | "_PRAGMA":
                return self._parse_pppragma_directive()
            case _:
                return self._parse_expression_statement()

    def _parse_attributed_statement(self) -> c_ast.Node:
        attributes = self._parse_attribute_specifier_sequence()
        if self._accept("SEMI"):
            return c_ast.AttributeDeclaration(attributes, attributes[0].coord)
        stmt = self._parse_statement()
        if isinstance(stmt, (c_ast.Label, c_ast.Case, c_ast.Default)):
