import ast
import sys
from pyflakes import checker
from pyflakes.reporter import Reporter


def check(codeString, filename, reporter=None):
    """
    Check the Python source given by C{codeString} for flakes.

    @param codeString: The Python source to check.
    @type codeString: C{str}

    @param filename: The name of the file the source came from, used to report
        errors.
    @type filename: C{str}

    @param reporter: A L{Reporter} instance, where errors and warnings will be
        reported.

    @return: The number of warnings emitted.
    @rtype: C{int}
    """
    if reporter is None:
        reporter = Reporter(sys.stdout, sys.stderr)

    tree = _parse_source(codeString, filename, reporter)
    if tree is None:
        return 1

    checker_instance = checker.Checker(tree, filename=filename)
    warnings = sorted(checker_instance.messages, key=lambda m: m.lineno)

    for warning in warnings:
        reporter.flake(warning)

    return len(warnings)


def _parse_source(codeString, filename, reporter):
    """
    Parse the source code and handle syntax errors.

    @param codeString: The Python source to parse.
    @type codeString: C{str}

    @param filename: The name of the file the source came from.
    @type filename: C{str}

    @param reporter: A L{Reporter} instance for reporting errors.
    @type reporter: L{Reporter}

    @return: The parsed AST, or None if an error occurred.
    @rtype: C{ast.AST} or C{None}
    """
    try:
        return ast.parse(codeString, filename=filename)
    except SyntaxError as e:
        reporter.syntaxError(filename, e.args[0], e.lineno, e.offset, e.text)
        return None
    except Exception:
        reporter.unexpectedError(filename, 'problem decoding source')
        return None
