def _lookup_style(style):
    if isinstance(style, str):
        return _lookup_style_by_name(style)
    return style


def _lookup_style_by_name(style_name):
    """
    Look up a style by its name.

    First checks the built-in styles, then plugin styles,
    and finally attempts to import a style module directly.
    """
    # Check built-in styles
    if style_name in _STYLE_NAME_TO_MODULE_MAP:
        mod_name, cls_name = _STYLE_NAME_TO_MODULE_MAP[style_name]
        return _import_style_class(mod_name, cls_name, is_builtin=True)

    # Check plugin styles
    for found_name, style_class in find_plugin_styles():
        if style_name == found_name:
            return style_class

    # Try to import as a module
    mod_name = 'pygments.styles.' + style_name
    cls_name = style_name.title() + 'Style'
    return _import_style_class(mod_name, cls_name, is_builtin=False)


def _import_style_class(mod_name, cls_name, is_builtin=False):
    """
    Import a style class from a module.

    Raises ClassNotFound if the module or class cannot be found.
    """
    try:
        mod = __import__(mod_name, None, None, [cls_name])
    except ImportError:
        builtin_msg = ', though it should be builtin' if is_builtin else ''
        raise ClassNotFound(f'Could not find style module {mod_name!r}{builtin_msg}.')

    try:
        return getattr(mod, cls_name)
    except AttributeError:
        raise ClassNotFound(f'Could not find style class {cls_name!r} in style module.')
```

