    def token_next(self, idx, skip_ws=True, skip_cm=False, _reverse=False):
        """Returns the next token relative to *idx*.

        If *skip_ws* is ``True`` (the default) whitespace tokens are ignored.
        If *skip_cm* is ``True`` comments are ignored.
        ``None`` is returned if there's no next token.
        """
        if idx is None:
            return None, None
        idx += 1  # alot of code usage current pre-compensates for this

        def matcher(tk):
            return not ((skip_ws and tk.is_whitespace)
                        or (skip_cm and imt(tk, t=T.Comment, i=Comment)))

        if _reverse:
            indexes = range(idx - 2, -1, -1)
        else:
            indexes = range(idx, len(self.tokens))

        for idx2 in indexes:
            token = self.tokens[idx2]
            if matcher(token):
                return (idx2, token)
        return (None, None)
