def token_next_by(self, i=None, m=None, t=None, idx=-1, end=None):
    """Return the index and token of the next token matching the given criteria.

    Args:
        i: Token index to match (optional).
        m: Token match pattern to match (optional).
        t: Token type to match (optional).
        idx: Starting index to search from (default: -1, i.e. start from beginning).
        end: Ending index to search up to (exclusive, default: end of list).

    Returns:
        A tuple of (index, token) if a matching token is found, otherwise (None, None).
    """
    idx += 1
    if idx is None:
        return None, None

    def _match(tk):
        return imt(tk, i, m, t)

    if end is None:
        end = len(self.tokens)

    for idx2 in range(idx, end):
        token = self.tokens[idx2]
        if _match(token):
            return idx2, token

    return None, None
