def _render_table(self, key: Key, table: Table, prefix: str | None = None) -> str:
    cur = ""

    if table.display_name is not None:
        _key = table.display_name
    else:
        _key = key.as_string()

        if prefix is not None:
            _key = prefix + "." + _key

    header_emitted = self._should_emit_header(table, key)
    if header_emitted:
        open_, close = self._get_table_brackets(table)

        newline_in_table_trivia = (
            "\n" if "\n" not in table.trivia.trail and len(table.value) > 0 else ""
        )
        cur += (
            f"{table.trivia.indent}"
            f"{open_}"
            f"{decode(_key)}"
            f"{close}"
            f"{table.trivia.comment_ws}"
            f"{decode(table.trivia.comment)}"
            f"{table.trivia.trail}"
            f"{newline_in_table_trivia}"
        )
    elif table.trivia.indent == "\n":
        cur += table.trivia.indent

    if header_emitted:
        # A super table opens no scope, so its fallbacks belong to -- and
        # were already written by -- the nearest enclosing header instead.
        for path, aot in _header_less_aots(table.value.body):
            cur += _render_empty_aot(path, aot)
    for k, v in table.value.body:
        if k is not None and _is_empty_aot(v):
            continue
        elif isinstance(v, Table):
            if self._needs_newline_before(cur, v):
                cur += "\n"
            assert k is not None
            if v.is_super_table():
                if k.is_dotted() and not key.is_dotted():
                    # Dotted key inside table
                    cur += self._render_table(k, v)
                else:
                    cur += self._render_table(k, v, prefix=_key)
            else:
                cur += self._render_table(k, v, prefix=_key)
        elif isinstance(v, AoT):
            if self._needs_newline_before(cur, v):
                cur += "\n"
            assert k is not None
            cur += self._render_aot(k, v, prefix=_key)
        else:
            cur += self._render_simple_item(
                k, v, prefix=_key if key.is_dotted() else None
            )

    return cur

    def _should_emit_header(self, table: Table, key: Key) -> bool:
        has_non_table_items = any(
            not isinstance(v2, (Table, AoT, Whitespace, Null))
            for _, v2 in table.value.body
        )
        has_dotted_table_keys = any(
            k2 is not None and k2.is_dotted()
            for k2, v2 in table.value.body
            if isinstance(v2, Table)
        )
        return (
            not table.is_super_table()
            or (has_non_table_items and not key.is_dotted())
            or (has_dotted_table_keys and not key.is_dotted())
        )

    def _get_table_brackets(self, table: Table) -> tuple[str, str]:
        if table.is_aot_element():
            return "[[", "]]"
        return "[", "]"

    def _needs_newline_before(self, cur: str, item: Item) -> bool:
        stripped = cur.strip(" ")
        return (
            stripped
            and not stripped.endswith("\n")
            and "\n" not in item.trivia.indent
        )
