    def _should_emit_table_header(self, key: Key, table: Table) -> bool:
        """Determine whether a table header should be emitted for the given table."""
        if not table.is_super_table():
            return True

        body = table.value.body

        has_non_table_items = any(
            not isinstance(v2, (Table, AoT, Whitespace, Null)) for _, v2 in body
        )
        has_dotted_table_keys = any(
            k2 is not None and k2.is_dotted()
            for k2, v2 in body
            if isinstance(v2, Table)
        )

        if key.is_dotted():
            return False

        return has_non_table_items or has_dotted_table_keys
