    def _parse_value(self) -> Item:
        """
        Attempts to parse a value at the current position.
        """
        self.mark()
        c = self._current
        trivia = Trivia()

        if c == StringType.SLB.value:
            with self._state:
                return self._parse_string(StringType.SLB)
            return
        elif c == StringType.SLL.value:
            return self._parse_literal_string()
        elif c == BoolType.TRUE.value[0]:
            return self._parse_true()
        elif c == BoolType.FALSE.value[0]:
            return self._parse_false()
        elif c == "[":
            return self._parse_nested(self._parse_array)
        elif c == "{":
            return self._parse_nested(self._parse_inline_table)
        elif c in "+-" or self._peek(4) in {
            "+inf",
            "-inf",
            "inf",
            "+nan",
            "-nan",
            "nan",
        }:
            return self._parse_number_value(trivia)
        elif c in string.digits:
            return self._parse_digit_value(trivia)
        else:
            raise self.parse_error(UnexpectedCharError, c)

    def _parse_number_value(self, trivia: Trivia) -> Item:
        """
        Parses a number that starts with a sign or is an inf/nan value.
        """
        self._src.advance_until(_NUM_STOP)
        raw = self.extract()

        item = self._parse_number(raw, trivia)
        if item is not None:
            return item

        raise self.parse_error(InvalidNumberError)

    def _parse_digit_value(self, trivia: Trivia) -> Item:
        """
        Parses a value that starts with a digit (Integer, Float, Date, Time or DateTime).
        """
        self._src.advance_until(_NUM_STOP)
        raw = self.extract()

        m = RFC_3339_LOOSE.match(raw)
        if m:
            if m.group("date") and m.group("time"):
                return self._parse_datetime(raw, trivia)
            if m.group("date"):
                return self._parse_date_or_datetime(raw, trivia)
            if m.group("time"):
                return self._parse_time(raw, trivia)

        item = self._parse_number(raw, trivia)
        if item is not None:
            return item

        raise self.parse_error(InvalidNumberError)

    def _parse_datetime(self, raw: str, trivia: Trivia) -> DateTime:
        """
        Parses a full RFC 3339 datetime string.
        """
        try:
            dt = parse_rfc3339(raw)
            assert isinstance(dt, datetime.datetime)
            return DateTime(
                dt.year,
                dt.month,
                dt.day,
                dt.hour,
                dt.minute,
                dt.second,
                dt.microsecond,
                dt.tzinfo,
                trivia,
                raw,
            )
        except ValueError:
            raise self.parse_error(InvalidDateTimeError) from None

    def _parse_date_or_datetime(self, raw: str, trivia: Trivia) -> Item:
        """
        Parses a date, potentially followed by a time component.
        """
        try:
            dt = parse_rfc3339(raw)
            assert isinstance(dt, datetime.date)
            date = Date(dt.year, dt.month, dt.day, trivia, raw)
            self.mark()
            self._src.advance_until(_DATE_TAIL_STOP)

            time_raw = self.extract()
            time_part = time_raw.rstrip()
            trivia.comment_ws = time_raw[len(time_part) :]
            if not time_part:
                return date

            dt = parse_rfc3339(raw + time_part)
            assert isinstance(dt, datetime.datetime)
            return DateTime(
                dt.year,
                dt.month,
                dt.day,
                dt.hour,
                dt.minute,
                dt.second,
                dt.microsecond,
                dt.tzinfo,
                trivia,
                raw + time_part,
            )
        except ValueError:
            raise self.parse_error(InvalidDateError) from None

    def _parse_time(self, raw: str, trivia: Trivia) -> Time:
        """
        Parses an RFC 3339 time string.
        """
        try:
            t = parse_rfc3339(raw)
            assert isinstance(t, datetime.time)
            return Time(
                t.hour,
                t.minute,
                t.second,
                t.microsecond,
                t.tzinfo,
                trivia,
                raw,
            )
        except ValueError:
            raise self.parse_error(InvalidTimeError) from None
