def check_partial(sig, args, kwargs):
    """ Like ``is_partial_args`` for the given signature spec"""
    num_pos_only, func, keyword_exclude, sigspec = sig
    if len(args) < num_pos_only:
        pad = (None,) * (num_pos_only - len(args))
        args = args + pad
    if keyword_exclude:
        kwargs = dict(kwargs)
        for item in keyword_exclude:
            kwargs.pop(item, None)
    sigspec2 = sigspec
    sigspec2, rv = _check_sigspec(sigspec2, func, _sigs._is_partial_args, func, args, kwargs)
    if sigspec2 is None:
        return rv
    try:
        sigspec2.bind_partial(*args, **kwargs)
    except TypeError:
        return False
    return True
```

