def interpose(el, seq):
    """ Introduce element between each pair of elements in seq

    >>> list(interpose("a", [1, 2, 3]))
    [1, 'a', 2, 'a', 3]
    >>> list(interpose("a", []))
    []
    """
    seq = iter(seq)
    try:
        first = next(seq)
    except StopIteration:
        return iter([])
    return itertools.chain(
        (first,),
        itertools.chain.from_iterable(
            ((el, item) for item in seq)
        )
    )
```

